#include <string>
#include <cstdint>
#include <cstring>

void PutFixed32(std::string* dst, uint32_t value) {
    char buf[4];
    memcpy(buf, &value, 4);
    dst->append(buf, 4);
}

int main() {
    std::string s;
    uint32_t v = 0x12345678;
    PutFixed32(&s, v);
    if (s.size() == 4) return 0;
    return 1;
}

